/* ---------- Bootstrap stats & UI ---------- */
function init() {
  const pages = new Set(CHUNKS.map(c => c.doc + "-" + c.page)).size;
  document.getElementById("statDocs").textContent = "4 à¹„à¸Ÿà¸¥à¹Œ";
  document.getElementById("statChunks").textContent = CHUNKS.length + " à¸ªà¹ˆà¸§à¸™";
  document.getElementById("statDocCount").textContent = "à¸«à¸™à¹‰à¸²à¹€à¸­à¸à¸ªà¸²à¸£: " + pages + " à¸«à¸™à¹‰à¸²";

  // donut + legend by doc share
  const counts = {};
  CHUNKS.forEach(c => counts[c.doc] = (counts[c.doc]||0) + 1);
  const total = CHUNKS.length;
  let gradParts = [], acc = 0, legendHtml = "";
  Object.keys(DOC_META).forEach(code => {
    const n = counts[code] || 0;
    const pct = total ? (n/total*100) : 0;
    const start = acc, end = acc + pct;
    gradParts.push(`${DOC_META[code].color} ${start}% ${end}%`);
    acc = end;
    legendHtml += `<div class="legend-item"><span class="legend-color" style="background:${DOC_META[code].color}"></span>${code} â€” ${pct.toFixed(0)}%</div>`;
  });
  document.getElementById("donutChart").style.background = `conic-gradient(${gradParts.join(",")})`;
  document.getElementById("donutLegend").innerHTML = legendHtml;

  // FAQ list
  document.getElementById("faqList").innerHTML = FAQS.map(q =>
    `<div class="faq-item" onclick="useQuestion(this)"><span>â€º ${q}</span></div>`
  ).join("");

  // Docs page grid
  const docStats = {};
  CHUNKS.forEach(c => {
    if (!docStats[c.doc]) docStats[c.doc] = { pages: new Set(), name: c.docName, chunks: 0 };
    docStats[c.doc].pages.add(c.page);
    docStats[c.doc].chunks++;
  });
  let docHtml = "";
  Object.keys(docStats).forEach(code => {
    const d = docStats[code];
    docHtml += `<div class="doc-card">
      <span class="doc-code" style="background:${DOC_META[code].color}22;color:${DOC_META[code].color}">${code}</span>
      <h4>${d.name}</h4>
      <div class="doc-meta">à¸ˆà¸³à¸™à¸§à¸™à¸«à¸™à¹‰à¸²: ${d.pages.size} à¸«à¸™à¹‰à¸² &nbsp;â€¢&nbsp; à¸ªà¹ˆà¸§à¸™à¸‚à¹‰à¸­à¸¡à¸¹à¸¥à¸—à¸µà¹ˆà¸ˆà¸±à¸”à¸—à¸³à¸”à¸±à¸Šà¸™à¸µ: ${d.chunks}</div>
    </div>`;
  });
  document.getElementById("docGrid").innerHTML = docHtml;
}

/* ---------- Retrieval: simple client-side keyword scoring over real text ---------- */
function scoreChunk(query, chunkText) {
  const q = query.trim();
  if (!q) return 0;
  let score = 0;
  if (chunkText.includes(q)) score += 60;
  const grams = (len) => {
    for (let i = 0; i + len <= q.length; i++) {
      const g = q.slice(i, i + len);
      if (g.trim().length < len) continue;
      if (chunkText.includes(g)) score += len;
    }
  };
  grams(8); grams(6); grams(4);
  return score;
}

function docBoost(query, doc) {
  const lower = query.toLowerCase();
  let boost = 0;
  if (doc === "DSBA" && (lower.includes("dsba") || lower.includes("à¸§à¸´à¸—à¸¢à¸²à¸à¸²à¸£à¸‚à¹‰à¸­à¸¡à¸¹à¸¥"))) boost += 25;
  if (doc === "AIT" && (lower.includes("ait") || lower.includes("à¸›à¸±à¸à¸à¸²à¸›à¸£à¸°à¸”à¸´à¸©à¸à¹Œ"))) boost += 25;
  if (doc === "IT-INTER" && (lower.includes("inter") || lower.includes("à¸™à¸²à¸™à¸²à¸Šà¸²à¸•à¸´") || lower.includes("à¸˜à¸¸à¸£à¸à¸´à¸ˆ"))) boost += 20;
  if (doc === "IT" && /(^|[^a-z])it([^a-z]|$)/.test(lower) && !lower.includes("inter")) boost += 15;
  return boost;
}

function retrieve(query, k) {
  const scored = CHUNKS.map(c => ({
    c, s: scoreChunk(query, c.text) + docBoost(query, c.doc)
  })).filter(x => x.s > 0);
  scored.sort((a, b) => b.s - a.s);
  // light diversity: avoid >3 chunks from the exact same page run
  const picked = [], seenPages = {};
  for (const x of scored) {
    const key = x.c.doc + "-" + x.c.page;
    seenPages[key] = (seenPages[key] || 0) + 1;
    if (seenPages[key] > 2) continue;
    picked.push(x.c);
    if (picked.length >= k) break;
  }
  return picked;
}

/* ---------- Ask flow ---------- */
let historyItems = [];

function useQuestion(el) {
  const q = el.textContent.replace("â€º", "").trim();
  document.getElementById("questionInput").value = q;
  askQuestion();
}

