function changePage(el, page) {
  document.querySelectorAll(".nav-item").forEach(i => i.classList.remove("active"));
  if (el) el.classList.add("active");
  document.querySelectorAll(".page-section").forEach(p => p.classList.add("hidden"));
  const target = document.getElementById("page-" + page);
  if (target) target.classList.remove("hidden");
}

function toggleTheme() {
  document.body.classList.toggle('dark-mode');
  const isDark = document.body.classList.contains('dark-mode');
  localStorage.setItem('theme', isDark ? 'dark' : 'light');
}

// Load theme on start
if (localStorage.getItem('theme') === 'dark') {
  document.body.classList.add('dark-mode');
}

/* --------- Toast --------- */
let toastTimer;
function showToast(message) {
  const toast = document.getElementById("toast");
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove("show"), 3000);
}

document.getElementById("questionInput").addEventListener("keydown", function (event) {
  if (event.key === "Enter" && (event.ctrlKey || event.metaKey)) { event.preventDefault(); askQuestion(); }
});

init();

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, m => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
}

function viewDocument(chunkId) {
  const c = CHUNKS.find(x => x.id === chunkId);
  if (!c) return;
  document.getElementById("modalTitle").textContent = "à¹€à¸­à¸à¸ªà¸²à¸£: " + c.docName;
  document.getElementById("modalMeta").innerHTML = "<b>à¸«à¸™à¹‰à¸²:</b> " + c.page + " | <b>à¸„à¸§à¸²à¸¡à¸¢à¸²à¸§:</b> " + c.text.length + " à¸•à¸±à¸§à¸­à¸±à¸à¸©à¸£";
  document.getElementById("modalText").innerHTML = escapeHtml(c.text).replace(/\n/g, "<br>");
  document.getElementById("modalOverlay").classList.add("show");
}

function closeModal() { document.getElementById("modalOverlay").classList.remove("show"); }
function closeModalOnOverlay(e) { if (e.target.id === "modalOverlay") closeModal(); }


function openManual() {
  document.getElementById("manualOverlay").classList.add("show");
}
function closeManual() {
  document.getElementById("manualOverlay").classList.remove("show");
}
// Update closeModalOnOverlay to handle manualOverlay
const oldCloseModalOnOverlay = closeModalOnOverlay;
closeModalOnOverlay = function(e) {
  if (e.target.id === "modalOverlay") closeModal();
  if (e.target.id === "manualOverlay") closeManual();
}


